const ALL = []

for (const wave of WAVES) {
  phase(wave.title)

  // WPs within a wave are independent → run concurrently.
  // isolation:'worktree' gives each its own worktree so parallel file edits never collide
  // (the disjoint-scope guarantee from 09 §"Intra-isolation"). Drop isolation for
  // read-only / analysis WPs by setting wp.tier-only and removing the flag at emit time.
  const results = (await parallel(wave.wps.map(wp => () =>
    agent(wp.brief, {
      label: wp.id,
      phase: wave.title,
      schema: WP_REPORT_SCHEMA,
      isolation: 'worktree',
      model: wp.tier || 'sonnet',
    })
  ))).filter(Boolean)
  ALL.push(...results)

  // Freeze-gate barrier. This wave gates everything downstream, so before moving on
  // we adversarially verify each WP's report against its DoD + the gate sign-off check.
  // A failed gate halts the run — "never proceed past a freeze gate without sign-off."
  if (wave.gate) {
    const verdicts = await parallel(results.map(r => () =>
      agent(
        `Adversarially verify work package ${r.id} for the "${wave.gate}" freeze gate. ` +
        `Confirm it meets its Definition of Done and the gate's sign-off check. ` +
        `Be skeptical; default passes=false if the evidence is thin.\n\nWP report:\n${r.report}`,
        { label: `verify:${r.id}`, phase: wave.title, schema: VERDICT_SCHEMA, model: 'opus' }
      )
    ))
    const failed = results.filter((r, i) => !verdicts[i] || !verdicts[i].passes)
    if (failed.length) {
      log(`Gate ${wave.gate} NOT signed off: ${failed.map(r => r.id).join(', ')} — halting for orchestrator review.`)
      return { halted: wave.gate, failed: failed.map(r => r.id), results: ALL, verdicts }
    }
    log(`Gate ${wave.gate} signed off — ${results.length} WP(s) verified.`)
  }
}

// Reports only. Orchestrator session reconciles 05 / Tasks / commits / merges next.
return { complete: true, results: ALL }
